109	/** Bind one surface. UI/outside interactions invalidate pending taps; multi-touch
110	 * cancels the gesture until every tracked contact lifts. Returns {reset,dispose}.
111	 */
112	export function attachTouchInput(surface, onIntent, options = {}) {
113	  const doc = surface.ownerDocument, win = doc.defaultView;
114	  const machine = createGestureMachine(options);
115	  const now = options.now ?? (() => win.performance.now());
116	  const uiSelector = options.uiSelector ??
117	    '[data-ui],button,a,input,select,textarea,[contenteditable="true"],[role="button"]';
118	  const listeners = [];
119	  const listen = (target, name, fn) => {
120	    target.addEventListener(name, fn, { capture: true, passive: false });
121	    listeners.push(() => target.removeEventListener(name, fn, true));
122	  };
123	  const sample = e => ({ pointerId: e.pointerId, x: e.clientX, y: e.clientY,
124	    time: now(), viewportWidth: doc.documentElement.clientWidth || win.innerWidth });
125	  listen(doc, 'pointerdown', e => {
126	    const path = e.composedPath?.() ?? [e.target];
127	    const inside = path.includes(surface) || surface.contains(e.target);
128	    const isUI = path.some(node => node.matches?.(uiSelector)) || !!e.target.closest?.(uiSelector);
129	    // After a mode reset, a second finger may arrive while the first is still down.
130	    // isPrimary protects that case even though reset discarded old pointer IDs.
131	    const ignored = !inside || isUI || e.button !== 0 ||
132	      (e.pointerType === 'touch' && e.isPrimary === false);
133	    machine.down({ ...sample(e), ignored });
134	    if (!ignored) {
135	      if (e.cancelable) e.preventDefault();
136	      try { surface.setPointerCapture(e.pointerId); } catch { /* Contact already ended. */ }
137	    }
138	  });
139	  listen(doc, 'pointermove', e => {
140	    // Preserve short excursions from coalesced samples so a drag-return is not a tap.
141	    const events = e.getCoalescedEvents?.() ?? [];
142	    for (const event of events) machine.move(sample(event));
143	    machine.move(sample(e));
144	  });
145	  listen(doc, 'pointerup', e => {
146	    for (const intent of machine.up(sample(e))) onIntent(intent);
147	  });
